preConditionHook:
// THE BAR THAT ENDS THE CLIMAX, not the climax itself. Bars 1..runBars were all
// with-trend trend bars -- StrongTrendBarRun's settled spike test, body at least
// bodyFraction of the bar's own range -- and THIS bar is not one. Brooks times
// the fade off the interruption: a small bar, a tailed bar, an inside bar, a
// doji or an opposite bar all end the run, so the break test is the NEGATION of
// the strong-trend-bar test and nothing narrower.
//
// NOT StrongTrendBarRun in the entry pane: that reads bars 0..N-1 and so is
// still true DURING the run, where this rule is true only on the bar after it.
// The lagged run cannot be produced by ANDing panes, which all evaluate at bar
// 0. NOT BuyOppositeColorBarAfterTrendBarRun either, which requires bar 0 to
// close DOWN -- a strictly narrower break test, so a small bull bar or a doji
// ends the run here and not there, and the two fire on different bars. NOT
// MomentumConsecutiveBars, which counts closes against the close N bars ago with
// no body test and no break term.
//
// The run is all-of-N in the StrongTrendBarRun shape: start true, let a failing
// bar clear the flag, loop unconditionally so EasyLanguage's lack of
// short-circuiting cannot matter. Every scratch value is a localVariables
// entry, never a hook-scope declaration, so the hooks survive a double
// placement; the flags persist across bars and are all reset before use.
//
// Product, not quotient, for the body test: EasyLanguage raises a runtime
// divide-by-zero and a zero-range bar is legal data.
//
// Deepest bar touched: runBars.
runUp = true;
runDn = true;
for (ii = 1; ii <= (int)runBars; ++ii) {
    if (el_le(close[ii], open[ii])) runUp = false;
    if (el_lt(close[ii] - open[ii], bodyFraction * (high[ii] - low[ii]))) runUp = false;
    if (el_ge(close[ii], open[ii])) runDn = false;
    if (el_lt(open[ii] - close[ii], bodyFraction * (high[ii] - low[ii]))) runDn = false;
}
nowUp = el_gt(close[0], open[0]) && el_ge(close[0] - open[0], bodyFraction * (high[0] - low[0]));
nowDn = el_lt(close[0], open[0]) && el_ge(open[0] - close[0], bodyFraction * (high[0] - low[0]));
